-- Modèles de cuve : la conversion hauteur → litres d'une CATÉGORIE de cuves
-- identiques, saisie une fois et partagée par les sites qui en sont équipés.
-- Le barème propre à un site (baremage_cuve) reste prioritaire : c'est le cas
-- particulier. La capacité d'un site rattaché est celle de son modèle.
--
-- Données initiales : les 4 catégories de cuves cylindriques du parc et les 3
-- barèmes fournis par l'exploitant le 07/10/2026 (DOC 1 à 3). DOC 1 et DOC 2
-- sont relevés en MILLIMÈTRES (convertis ici en cm), DOC 3 en centimètres.
-- DOC 2, hauteur 504 mm : la cellule portait « 939+ », lue 939 L (cohérent
-- avec 934 et 944 L de part et d'autre).

CREATE TABLE "modeles_cuve" (
  "id" TEXT NOT NULL,
  "nom" VARCHAR(60) NOT NULL,
  "capacite_litres" DECIMAL(8,2) NOT NULL,
  "forme_cuve" "FormeCuve",
  "longueur_cm" DECIMAL(6,1),
  "largeur_cm" DECIMAL(6,1),
  "hauteur_cm" DECIMAL(6,1),
  "diametre_cm" DECIMAL(6,1),
  "description" VARCHAR(300),
  "is_active" BOOLEAN NOT NULL DEFAULT true,
  "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updated_at" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "modeles_cuve_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "modeles_cuve_nom_key" ON "modeles_cuve"("nom");

CREATE TABLE "baremage_modele_cuve" (
  "id" TEXT NOT NULL,
  "modele_id" TEXT NOT NULL,
  "hauteur_cm" DECIMAL(6,1) NOT NULL,
  "litres" DECIMAL(8,1) NOT NULL,
  CONSTRAINT "baremage_modele_cuve_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "baremage_modele_cuve_modele_id_fkey" FOREIGN KEY ("modele_id")
    REFERENCES "modeles_cuve"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "baremage_modele_cuve_modele_id_hauteur_cm_key" ON "baremage_modele_cuve"("modele_id", "hauteur_cm");

-- RESTRICT : un modèle porté par des sites ne se supprime pas (on le désactive).
ALTER TABLE "sites" ADD COLUMN "modele_cuve_id" TEXT;
ALTER TABLE "sites" ADD CONSTRAINT "sites_modele_cuve_id_fkey" FOREIGN KEY ("modele_cuve_id")
  REFERENCES "modeles_cuve"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE INDEX "sites_modele_cuve_id_idx" ON "sites"("modele_cuve_id");


